using System;using System.IO;using System.Text;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
public static class ManualHypotheses {
 public const string FileName="manual-hypotheses.json";public static void RequireWritable(string root){if(File.Exists(Path.Combine(root,".readonly-research-preview")))throw new InvalidDataException("Historical archive snapshot is read-only; no manual work changed.");}
 public sealed class Record {public string Id,Text;public Dictionary<string,object>Data;}
 public sealed class Result {public readonly List<Record>Records=new List<Record>();public readonly List<string>Errors=new List<string>();public readonly List<string>OriginWarnings=new List<string>();}
 public static Dictionary<string,object>D(object o){return o as Dictionary<string,object>??new Dictionary<string,object>();}public static object V(Dictionary<string,object>d,string k){return d.ContainsKey(k)?d[k]:null;}public static string S(Dictionary<string,object>d,string k){return Convert.ToString(V(d,k));}public static IEnumerable<object>A(object o){if(o is IEnumerable&&!(o is string)&&!(o is IDictionary))foreach(var x in (IEnumerable)o)yield return x;}
 static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128};}public static string Serialize(object o){return Json().Serialize(o);}static Dictionary<string,object>Parse(string s){return LocalJson.ParseObject(s);}static bool Integer(object o){return o is int||o is long;}
 public static void Validate(Dictionary<string,object>note){if(S(note,"schema")!="reveng-manual-hypothesis-v1"||S(note,"origin")!="LOCAL_MANUAL_INPUT_NOT_MODEL_OUTPUT"||S(note,"status")!="DRAFT_UNVERIFIED"||!Object.Equals(V(note,"auto_admission"),false))throw new InvalidDataException("Manual draft policy mismatch");if(S(note,"supersedes")!=""&&!System.Text.RegularExpressions.Regex.IsMatch(S(note,"supersedes"),"^[0-9a-f]{64}$"))throw new InvalidDataException("Invalid previous manual revision ID");foreach(string k in new[]{"title","interpretation","assumptions","next_action","success","failure"})if(String.IsNullOrWhiteSpace(S(note,k))||S(note,k).Length>(k=="title"?200:4000))throw new InvalidDataException("Заполните поле: "+k+"; не выдавайте неизвестное за факт.");var source=D(V(note,"source_snapshot"));string text=S(source,"text");if(text.Length>1048576)throw new InvalidDataException("Manual source snapshot exceeds1048576 UTF-16 units; source is not truncated or repaired");if(text==""||ProvenanceAudit.Sha(text)!=S(source,"text_sha256"))throw new InvalidDataException("Manual source snapshot hash mismatch");var r=D(V(note,"reference"));if(!Integer(V(r,"start"))||!Integer(V(r,"end")))throw new InvalidDataException("Codepoint ranges must be integers");int start=Convert.ToInt32(r["start"]),end=Convert.ToInt32(r["end"]);if(start<0||end<=start||end-start>1000||S(r,"text_sha256")!=S(source,"text_sha256")||ProvenanceAudit.Slice(text,start,end)!=S(r,"quote"))throw new InvalidDataException("Выделите точную цитату целиком, длиной до1000 символов Unicode.");if(S(note,"customer_status")!="UNVERIFIED"||S(note,"demand_status")!="UNVERIFIED")throw new InvalidDataException("Manual draft cannot verify customers or demand");}
 public static Dictionary<string,object>Create(Dictionary<string,object>source,int start,int end,Dictionary<string,string>fields){var note=new Dictionary<string,object>{{"schema","reveng-manual-hypothesis-v1"},{"origin","LOCAL_MANUAL_INPUT_NOT_MODEL_OUTPUT"},{"status","DRAFT_UNVERIFIED"},{"created_at",DateTimeOffset.UtcNow.ToString("o")},{"auto_admission",false},{"customer_status","UNVERIFIED"},{"demand_status","UNVERIFIED"},{"source_snapshot",Parse(Serialize(source))},{"reference",new Dictionary<string,object>{{"text_sha256",S(source,"text_sha256")},{"start",start},{"end",end},{"quote",ProvenanceAudit.Slice(S(source,"text"),start,end)}}}};foreach(var p in fields){if(!new[]{"title","interpretation","assumptions","buyer_role","next_action","success","failure"}.Contains(p.Key))throw new InvalidDataException("Unexpected manual field");note[p.Key]=(p.Value??"").Trim();}Validate(note);return note;}
 static List<object>ReadRaw(string root){string path=Path.Combine(root,FileName);if(!File.Exists(path)&&File.Exists(LocalJson.BackupPath(path)))throw new InvalidDataException("Manual primary missing; previous copy retained for inspection, writes blocked");return ReadPath(path);}
 static List<object>ReadPath(string path){if(!File.Exists(path))return new List<object>();var info=new FileInfo(path);if(info.Length>8388608)throw new InvalidDataException("Manual notes exceed8MiB");var wrap=LocalJson.ReadObject(path);string payload=S(wrap,"payload_json");if(ProvenanceAudit.Sha(payload)!=S(wrap,"payload_sha256"))throw new InvalidDataException("Manual notes root hash mismatch");var state=Parse(payload);if(S(state,"schema")!="reveng-manual-hypotheses-v1")throw new InvalidDataException("Unsupported manual notes schema");if(!(V(state,"notes") is IList))throw new InvalidDataException("Manual notes array missing or invalid; existing file preserved");return A(V(state,"notes")).ToList();}
 public static Result Load(string root){var result=new Result();try{var seen=new HashSet<string>();foreach(var entry in ReadRaw(root)){try{var w=D(entry);string payload=S(w,"payload_json"),id=S(w,"payload_sha256");if(ProvenanceAudit.Sha(payload)!=id||!seen.Add(id))throw new InvalidDataException("Manual note hash mismatch or duplicate");var note=Parse(payload);Validate(note);if(S(note,"supersedes")!=""&&!result.Records.Any(r=>r.Id==S(note,"supersedes")))throw new InvalidDataException("Prior manual revision missing or out of order; existing file preserved.");string warning="";try{EvidenceBindings.Check(root,D(V(note,"source_snapshot")),false);}catch(Exception ex){warning="СВЯЗЬ ИСТОЧНИКА СЕЙЧАС НЕ ПОДТВЕРЖДЕНА: "+ex.Message+". Снимок заметки не выдан за проверенный источник.\r\n";result.OriginWarnings.Add(warning);}result.Records.Add(new Record{Id=id,Data=note,Text=warning+Describe(note,id)});}catch(Exception ex){result.Errors.Add(ex.Message);}}}catch(Exception ex){result.Errors.Add(ex.Message);}return result;}
 public static string DescribePrevious(string root){string path=Path.Combine(root,FileName),previous=LocalJson.BackupPath(path);if(!File.Exists(previous)||Load(root).Errors.Count==0)return "";var b=new StringBuilder("PREVIOUS MANUAL NOTES / Предыдущая копия заметок. Только чтение; не текущие записи.\r\n");b.AppendLine("Копия может не содержать последнее сохранение. Слияние и замена primary не выполнялись. Запись заблокирована до разрешения ошибки primary.");try{var seen=new HashSet<string>();foreach(var entry in ReadPath(previous)){var w=D(entry);string payload=S(w,"payload_json"),id=S(w,"payload_sha256");if(ProvenanceAudit.Sha(payload)!=id||!seen.Add(id))throw new InvalidDataException("Previous note hash mismatch or duplicate");var note=Parse(payload);Validate(note);if(S(note,"supersedes")!=""&&!seen.Contains(S(note,"supersedes")))throw new InvalidDataException("Previous revision missing or out of order");b.AppendLine(Describe(note,id));}return b.ToString();}catch(Exception ex){if(ex is OutOfMemoryException)throw;return "PREVIOUS MANUAL NOTES UNREADABLE; bytes preserved: "+ex.Message;}}
 public static string Save(string root,Dictionary<string,object>note){RequireWritable(root);Validate(note);EvidenceBindings.Check(root,D(V(note,"source_snapshot")),false);string payload=Serialize(note),id=ProvenanceAudit.Sha(payload),path=Path.Combine(root,FileName);using(var gate=new FileStream(Path.Combine(root,"manual-hypotheses.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){var checkedState=Load(root);if(checkedState.Errors.Count>0)throw new InvalidDataException("Заметки не записаны: существующий файл повреждён; исходный файл сохранён без ремонта.");if(checkedState.Records.Any(r=>r.Id==id))return id;if(S(note,"supersedes")!=""&&!checkedState.Records.Any(r=>r.Id==S(note,"supersedes")))throw new InvalidDataException("Предыдущая ручная ревизия не найдена; история не изменена.");if(S(note,"supersedes")!=""&&checkedState.Records.Any(r=>S(r.Data,"supersedes")==S(note,"supersedes")))throw new InvalidDataException("Another revision already supersedes this note; reopen the latest revision. Existing history and editor recovery are preserved.");if(S(note,"supersedes")!=""){var previous=checkedState.Records.Single(r=>r.Id==S(note,"supersedes"));var before=D(V(previous.Data,"source_snapshot"));var after=D(V(note,"source_snapshot"));if(S(before,"url")!=S(after,"url")||S(before,"kind")!=S(after,"kind")||(S(before,"url")==""&&S(before,"text_sha256")!=S(after,"text_sha256")))throw new InvalidDataException("A revision cannot silently retarget another source; save a separate hypothesis.");}var notes=ReadRaw(root);notes.Add(new Dictionary<string,object>{{"payload_json",payload},{"payload_sha256",id}});string state=Serialize(new Dictionary<string,object>{{"schema","reveng-manual-hypotheses-v1"},{"notes",notes}});string serialized=Serialize(new Dictionary<string,object>{{"payload_json",state},{"payload_sha256",ProvenanceAudit.Sha(state)}});if(Encoding.UTF8.GetByteCount(serialized)>8388608)throw new InvalidDataException("Manual notes exceed8MiB; existing notes preserved");string temp=LocalJson.TemporaryPath(path);try{LocalJson.WriteTemporary(temp,serialized);if(File.Exists(path))File.Replace(temp,path,LocalJson.BackupPath(path));else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}return id;}
 public static string Describe(Dictionary<string,object>n,string id){var s=D(V(n,"source_snapshot"));var r=D(V(n,"reference"));var b=new StringBuilder("РУЧНАЯ ГИПОТЕЗА — непроверенный черновик, не результат AI и не бизнес-кандидат\r\n");b.AppendLine(S(n,"title")).AppendLine("Предыдущая ручная ревизия: "+S(n,"supersedes")+". Ревизия не означает подтверждения гипотезы.").AppendLine("ID: "+id+" | создано: "+S(n,"created_at")).AppendLine("Источник: "+S(s,"url")).AppendLine("Автор источника: "+S(s,"author")+" | роль: "+S(s,"kind")).AppendLine("Область/неполнота: "+S(s,"text_scope")).AppendLine("Получено: "+S(s,"captured_at")+" | SHA256: "+S(s,"text_sha256")).AppendLine("Точная цитата codepoint ["+S(r,"start")+","+S(r,"end")+"):").AppendLine(S(r,"quote")).AppendLine("Цитата подтверждает только наличие этих слов. Причина проблемы, правильность ответа, покупатель и спрос не доказаны.");foreach(var p in new[]{new[]{"interpretation","Моя интерпретация / гипотеза"},new[]{"assumptions","Допущения и неизвестное"},new[]{"buyer_role","Предполагаемая роль покупателя — НЕ клиент"},new[]{"next_action","Следующий шаг — НЕ выполнен"},new[]{"success","Критерий успеха"},new[]{"failure","Отрицательный результат"}})b.AppendLine(p[1]+": "+S(n,p[0]));b.AppendLine("AUTO_ADMISSION=false; customer/demand=UNVERIFIED; решения владельца и исходные результаты модели не изменены.").AppendLine("Полный сохранённый снимок поля:").AppendLine(S(s,"text"));return b.ToString();}
}
